use std::rc::Rc;

impl Solution {
    pub fn flatten(root: &mut Option<Rc<RefCell<TreeNode>>>) {
        fn pre(n: &Option<Rc<RefCell<TreeNode>>>, out: &mut Vec<Rc<RefCell<TreeNode>>>) {
            if let Some(rc) = n {
                out.push(rc.clone());
                pre(&rc.borrow().left, out);
                pre(&rc.borrow().right, out);
            }
        }
        let mut nodes = Vec::new();
        pre(root, &mut nodes);
        for i in 0..nodes.len() {
            let mut b = nodes[i].borrow_mut();
            b.left = None;
            b.right = nodes.get(i + 1).cloned();
        }
    }
}

